from ..auth.deps import tenant_session_admin
from ..models import Organization
from ..services import api_keys as api_key_service


router = APIRouter(prefix="/settings", tags=["settings"])


def _org_settings(org: Organization) -> Dict[str, Any]:
    return org.settings or {}


def _update_org_settings(session, org: Organization, new_settings: Dict[str, Any]):
    org.settings = new_settings
    session.add(org)
    session.commit()
    session.refresh(org)


class ApiKeyCreatePayload(BaseModel):
    name: str = Field(..., max_length=255)
    scopes: List[str] = Field(default_factory=list)
    expires_in_days: int | None = Field(default=None, gt=0, le=365)
    auth_method: str = Field(default="api_key")


@router.get("/api-keys")
def list_api_keys(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    keys = api_key_service.list_api_keys(session, identity.org_id)
    return {"items": [
        {
            "id": str(key.id),
            "name": key.name,
            "prefix": key.prefix,
            "scopes": key.scopes or [],
            "auth_method": key.auth_method,
            "created_at": key.created_at,
            "expires_at": key.expires_at,
            "last_used_at": key.last_used_at,
        }
        for key in keys
    ]}


@router.post("/api-keys")
def create_api_key(payload: ApiKeyCreatePayload, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    record, plaintext = api_key_service.create_api_key(
        session,
        org_id=identity.org_id,
        name=payload.name,
        scopes=payload.scopes,
        auth_method=payload.auth_method,
        created_by_user_id=identity.user_id,
        expires_in_days=payload.expires_in_days,
    )
    return {
        "id": str(record.id),
        "name": record.name,
        "prefix": record.prefix,
        "token": plaintext,
        "scopes": record.scopes or [],
        "auth_method": record.auth_method,
    }


@router.delete("/api-keys/{key_id}")
def delete_api_key(key_id: str, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    if not api_key_service.revoke_api_key(session, api_key_id=key_id, org_id=identity.org_id):
        raise HTTPException(status_code=404, detail="Key not found")
    return {"success": True}


@router.get("/thresholds")
def get_thresholds(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = session.get(Organization, identity.org_id)
    thresholds = (_org_settings(org).get("thresholds") if org else None) or {}
    return thresholds


@router.put("/thresholds")
def update_thresholds(payload: dict, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = session.get(Organization, identity.org_id)
    if not org:
        raise HTTPException(status_code=404, detail="Org not found")
    settings = _org_settings(org)
    settings["thresholds"] = payload
    _update_org_settings(session, org, settings)
    return payload


@router.get("/models")
def list_models(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = session.get(Organization, identity.org_id)
    models = (_org_settings(org).get("models") if org else None) or []
    return {"items": models}

