import axios from 'axios';
import { getSession } from '../utils/auth';

const fastapiClient = axios.create({
  baseURL: import.meta.env.VITE_FASTAPI_URL || 'http://localhost:8000',
  headers: {
    'Content-Type': 'application/json'
  },
  timeout: 10000
});

fastapiClient.interceptors.request.use((config) => {
  const { token, role, org } = getSession();
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  if (role) {
    (config.headers as any)['RG-Role'] = role;
  }
  if (org) {
    (config.headers as any)['RG-Org-ID'] = org;
  }
  return config;
});

fastapiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error('FastAPI Error:', error?.response || error);
    return Promise.reject(error?.response?.data || { error: 'Network error' });
  },
);

export default fastapiClient;

import React, { useEffect, useState } from 'react';
import { fetchAuditLogs, AuditEntry } from '../../api/audit';
import AuditFilters from './AuditFilters';
import AuditLogsTable from './AuditLogsTable';
import MetadataModal from './MetadataModal';

const ITEMS_PER_PAGE = 50;

const AuditLogsPage = () => {
  const [logs, setLogs] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [actionFilter, setActionFilter] = useState('');
  const [selectedMetadata, setSelectedMetadata] = useState<Record<string, unknown> | null>(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await fetchAuditLogs({ page, limit: ITEMS_PER_PAGE });
      setLogs(res.items);
    } catch (error) {
      console.error('Audit logs load error:', error);
    }
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, [page]);

  if (loading) {
    return <div>Loading Audit Logs…</div>;
  }

  const filteredLogs = logs.filter((log) => {
    const term = search.toLowerCase();
    const matchesSearch =
      term.length === 0 ||
      log.user.toLowerCase().includes(term) ||
      log.action.toLowerCase().includes(term) ||
      JSON.stringify(log.metadata).toLowerCase().includes(term);

    const matchesAction = !actionFilter || log.action === actionFilter;

    return matchesSearch && matchesAction;
  });

  return (
    <div>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Audit Logs</h1>

      <AuditFilters
        search={search}
        setSearch={setSearch}
        actionFilter={actionFilter}
        setActionFilter={setActionFilter}
      />

      <AuditLogsTable logs={filteredLogs} onOpenMetadata={setSelectedMetadata} />

      <div style={{ marginTop: '20px', display: 'flex', gap: '20px' }}>
        <button
          disabled={page <= 1}
          onClick={() => setPage((prev) => Math.max(1, prev - 1))}
          style={{
            padding: '8px 14px',
            borderRadius: '6px',
            border: '1px solid var(--rg-border)',
            background: 'var(--rg-bg-card)',
            color: 'var(--rg-text)'
          }}
        >
          Prev
        </button>
        <button
          disabled={logs.length < ITEMS_PER_PAGE}
          onClick={() => setPage((prev) => prev + 1)}
          style={{
            padding: '8px 14px',
            borderRadius: '6px',
            border: '1px solid var(--rg-border)',
            background: 'var(--rg-bg-card)',
            color: 'var(--rg-text)'
          }}
        >
          Next
        </button>
        <div style={{ color: 'var(--rg-text-light)' }}>Page {page}</div>
      </div>

      {selectedMetadata && (
        <MetadataModal data={selectedMetadata} onClose={() => setSelectedMetadata(null)} />
      )}
    </div>
  );
};

export default AuditLogsPage;

