from __future__ import annotations

from typing import List

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, EmailStr, Field
from sqlalchemy import select

from ..auth.deps import require_roles, tenant_session_admin
from ..models import OrgMembership, Organization, User


router = APIRouter(prefix="/orgs", tags=["organizations"])


class OrgSummary(BaseModel):
    id: str
    name: str
    plan: str
    status: str


@router.get("", response_model=List[OrgSummary])
def list_orgs(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    orgs = session.exec(
        select(Organization)
        .where(
            (Organization.id == identity.org_id)
            if not identity.allows_cross_org()
            else Organization.id.is_not(None)
        )
        .order_by(Organization.created_at.desc())
    ).all()
    return [
        OrgSummary(id=str(org.id), name=org.name, plan=org.plan, status=org.status)
        for org in orgs
    ]


class OrgCreateRequest(BaseModel):
    name: str = Field(..., max_length=255)
    plan: str = Field(default="free", max_length=50)
    slug: str = Field(..., max_length=128)


@router.post("", response_model=OrgSummary)
def create_org(payload: OrgCreateRequest, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    if not identity.allows_cross_org():
        raise HTTPException(status_code=403, detail="Only global admins can create orgs")

    exists = session.exec(
        select(Organization).where(Organization.slug == payload.slug)
    ).first()
    if exists:
        raise HTTPException(status_code=409, detail="Slug already in use")

    org = Organization(
        name=payload.name,
        plan=payload.plan,
        slug=payload.slug,
    )
    session.add(org)
    session.commit()
    session.refresh(org)
    return OrgSummary(id=str(org.id), name=org.name, plan=org.plan, status=org.status)


@router.get("/current", response_model=OrgSummary)
def current_org(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = session.get(Organization, identity.org_id)
    if not org:
        raise HTTPException(status_code=404, detail="Org not found")
    return OrgSummary(id=str(org.id), name=org.name, plan=org.plan, status=org.status)


class InviteRequest(BaseModel):
    email: EmailStr
    role: str = Field(default="viewer", max_length=50)


@router.post("/invite", status_code=201)
def invite_user(
    payload: InviteRequest,
    session_identity=Depends(tenant_session_admin),
):
    session, identity = session_identity
    user = session.exec(select(User).where(User.email == payload.email)).first()
    if not user:
        user = User(email=payload.email, status="invited")
        session.add(user)
        session.commit()
        session.refresh(user)

    existing = session.exec(
        select(OrgMembership).where(
            OrgMembership.user_id == user.id,
            OrgMembership.org_id == identity.org_id,
        )
    ).first()
    if existing:
        raise HTTPException(status_code=409, detail="User already in org")

    membership = OrgMembership(
        user_id=user.id,
        org_id=identity.org_id,
        role=payload.role,
        status="invited",
    )
    session.add(membership)
    session.commit()
    return {"id": str(membership.id), "user_id": str(user.id), "role": membership.role}


class RoleUpdateRequest(BaseModel):
    role: str = Field(..., max_length=50)
    status: str = Field(default="active", max_length=50)


@router.put("/users/{user_id}", status_code=200)
def update_user_role(
    user_id: str,
    payload: RoleUpdateRequest,
    session_identity=Depends(tenant_session_admin),
    identity=Depends(require_roles("admin")),
):
    session, _ = session_identity
    membership = session.exec(
        select(OrgMembership).where(
            OrgMembership.user_id == user_id,
            OrgMembership.org_id == identity.org_id,
        )
    ).first()
    if not membership:
        raise HTTPException(status_code=404, detail="Membership not found")
    membership.role = payload.role
    membership.status = payload.status
    session.add(membership)
    session.commit()
    return {"success": True}


@router.get("/members")
def list_members(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    memberships = session.exec(
        select(OrgMembership)
        .where(OrgMembership.org_id == identity.org_id)
        .order_by(OrgMembership.created_at.desc())
    ).all()
    results = []
    for member in memberships:
        user = session.get(User, member.user_id)
        results.append(
            {
                "id": str(member.id),
                "user_id": str(member.user_id),
                "email": user.email if user else None,
                "role": member.role,
                "status": member.status,
                "created_at": member.created_at,
            }
        )
    return {"items": results}

from __future__ import annotations

from datetime import datetime
from typing import Any, Dict
import uuid

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field
from sqlalchemy import desc, select

from ..auth.deps import tenant_session_admin
from ..models import BillingRecord, Organization


router = APIRouter(prefix="/billing", tags=["billing"])


def _get_org(session, org_id):
    org = session.get(Organization, org_id)
    if not org:
        raise HTTPException(status_code=404, detail="Org not found")
    return org


def _get_settings(org: Organization) -> Dict[str, Any]:
    return org.settings or {}


@router.get("/overview")
def billing_overview(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = _get_org(session, identity.org_id)
    record = session.exec(
        select(BillingRecord)
        .where(BillingRecord.org_id == identity.org_id, BillingRecord.deleted_at.is_(None))
        .order_by(desc(BillingRecord.period_start))
    ).first()

    overview = {
        "plan": org.plan,
        "status": org.status,
    }
    usage = {}
    invoices = []
    if record:
        overview.update(
            {
                "period_start": record.period_start.isoformat(),
                "period_end": record.period_end.isoformat(),
                "amount_due_cents": record.amount_due_cents,
                "currency": record.currency,
                "billing_status": record.status,
            }
        )
        usage = record.usage or {}
        invoices.append(
            {
                "period_start": record.period_start.isoformat(),
                "period_end": record.period_end.isoformat(),
                "amount_due_cents": record.amount_due_cents,
                "currency": record.currency,
                "status": record.status,
                "invoice_url": record.invoice_url,
            }
        )

    settings = _get_settings(org)
    payment_methods = settings.get("payment_methods", [])
    return {
        "overview": overview,
        "usage": usage,
        "invoices": invoices,
        "payment_methods": payment_methods,
        "plan": org.plan,
    }


class PlanChangeRequest(BaseModel):
    plan: str = Field(..., max_length=50)


@router.post("/change-plan")
def change_plan(payload: PlanChangeRequest, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = _get_org(session, identity.org_id)
    org.plan = payload.plan
    session.add(org)
    session.commit()
    return {"success": True, "plan": org.plan}


@router.post("/payment-methods")
def add_payment_method(session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = _get_org(session, identity.org_id)
    settings = _get_settings(org)
    payment_methods = settings.setdefault("payment_methods", [])
    method = {
        "id": f"pm-{uuid.uuid4().hex[:8]}",
        "brand": "Visa",
        "last4": str(uuid.uuid4().int)[-4:],
        "exp": "12/28",
        "added_at": datetime.utcnow().isoformat(),
    }
    payment_methods.append(method)
    org.settings = settings
    session.add(org)
    session.commit()
    return {"redirect_url": "https://billing.resonantgraph.com/payment"}


@router.delete("/payment-methods/{pm_id}")
def delete_payment_method(pm_id: str, session_identity=Depends(tenant_session_admin)):
    session, identity = session_identity
    org = _get_org(session, identity.org_id)
    settings = _get_settings(org)
    payment_methods = settings.get("payment_methods", [])
    filtered = [m for m in payment_methods if m.get("id") != pm_id]
    if len(filtered) == len(payment_methods):
        raise HTTPException(status_code=404, detail="Payment method not found")
    settings["payment_methods"] = filtered
    org.settings = settings
    session.add(org)
    session.commit()
    return {"success": True}

import React, { useEffect, useState } from 'react';
import { fetchPolicies, createPolicy, deletePolicy, updatePolicy } from '../../api/policies';
import PolicyTable from './PolicyTable';
import CreatePolicyModal from './CreatePolicyModal';
import EditPolicyModal from './EditPolicyModal';

const PoliciesPage = () => {
  const [policies, setPolicies] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const [editPolicy, setEditPolicy] = useState<any>(null);

  const load = async () => {
    setLoading(true);
    const items = await fetchPolicies();
    setPolicies(items);
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const filtered = policies.filter((p) => p.name.toLowerCase().includes(search.toLowerCase()));

  const handleCreate = async (payload: any) => {
    await createPolicy(payload);
    await load();
    setShowCreate(false);
  };

  const handleDelete = async (id: string) => {
    await deletePolicy(id);
    await load();
  };

  const handleUpdate = async (id: string, payload: any) => {
    await updatePolicy(id, payload);
    await load();
    setEditPolicy(null);
  };

  if (loading) return <div>Loading policies…</div>;

  return (
    <div>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Policies</h1>
      <div style={{ marginTop: 20, marginBottom: 20, display: 'flex', gap: 20 }}>
        <input
          style={{ padding: '10px 12px', borderRadius: '6px', border: '1px solid var(--rg-border)', flexGrow: 1, background: 'var(--rg-bg)', color: 'var(--rg-text)' }}
          placeholder="Search policies…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button
          onClick={() => setShowCreate(true)}
          style={{ background: 'var(--rg-primary)', color: '#fff', padding: '10px 16px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
        >
          + New Policy
        </button>
      </div>
      <PolicyTable items={filtered} onDelete={handleDelete} onEdit={(p) => setEditPolicy(p)} />
      {showCreate && <CreatePolicyModal onClose={() => setShowCreate(false)} onSubmit={handleCreate} />}
      {editPolicy && (
        <EditPolicyModal
          policy={editPolicy}
          onClose={() => setEditPolicy(null)}
          onSubmit={(payload) => handleUpdate(editPolicy.id, payload)}
        />
      )}
    </div>
  );
};

export default PoliciesPage;

