router = APIRouter(prefix="/predictions", tags=["predictions"])


class PredictionSummary(BaseModel):
    id: str
    external_id: Optional[str]
    status: str
    validity: Optional[float]
    entropy: Optional[float]
    anchor_probability: Optional[float]
    policies_triggered: List[str]
    created_at: str


def _serialize(pred: PredictionRecord) -> PredictionSummary:
    return PredictionSummary(
        id=str(pred.id),
        external_id=pred.external_id,
        status=pred.status,
        validity=pred.validity,
        entropy=pred.entropy,
        anchor_probability=pred.anchor_probability,
        policies_triggered=pred.policies_triggered or [],
        created_at=pred.created_at.isoformat(),
    )


@router.get("", response_model=List[PredictionSummary])
def list_predictions(limit: int = 50, session=Depends(tenant_session)):
    preds = session.exec(
        select(PredictionRecord)
        .where(PredictionRecord.deleted_at.is_(None))
        .order_by(desc(PredictionRecord.created_at))
        .limit(limit)
    ).all()
    return [_serialize(pred) for pred in preds]


@router.get("/{prediction_id}")
def prediction_detail(prediction_id: str, session=Depends(tenant_session)):
    record = session.get(PredictionRecord, prediction_id)
    if not record or record.deleted_at is not None:
        raise HTTPException(status_code=404, detail="Prediction not found")
    data = record.dict()
    data["id"] = str(record.id)
    return data


@router.get("/evidence/{prediction_id}")
def prediction_evidence(prediction_id: str, session=Depends(tenant_session)):
    record = session.get(PredictionRecord, prediction_id)
    if not record or record.deleted_at is not None:
        raise HTTPException(status_code=404, detail="Prediction not found")
    return record.evidence_graph or {}


class PredictionCreateRequest(BaseModel):
    input_text: str = Field(..., min_length=1)
    context: Optional[dict] = None


@router.post("", response_model=PredictionSummary, status_code=201)
def create_prediction(payload: PredictionCreateRequest, session=Depends(tenant_session)):
    result = ml_client.predict(payload.input_text, payload.context)
    record = PredictionRecord(
        external_id=None,
        status="completed",
        org_id=session.info.get("org_id"),
        is_global=False,
        validity=result.get("validity"),
        entropy=result.get("entropy"),
        anchor_probability=result.get("metadata", {}).get("anchor_probability"),
        policies_triggered=result.get("metadata", {}).get("policies", []),
        evidence_graph=result.get("metadata", {}).get("evidence"),
        payload={"input_text": payload.input_text},
    )
    session.add(record)
    session.commit()
    session.refresh(record)
    return _serialize(record)


