from __future__ import annotations

from typing import Any, Dict, List, Optional

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field

from .auth import verify_internal_key
from .model_store import get_model_version, list_model_versions
from ml.offline_embedder import embed_text

router = APIRouter()


@router.get("/health")
def health():
    return {"status": "ok"}


class PredictRequest(BaseModel):
    input_text: str = Field(..., min_length=1)
    context: Optional[Dict[str, Any]] = None


class PredictResponse(BaseModel):
    validity: float
    entropy: float
    anchors: List[str]
    metadata: Dict[str, Any]


@router.post("/predict", response_model=PredictResponse, dependencies=[Depends(verify_internal_key)])
def predict(payload: PredictRequest):
    vector = embed_text(payload.input_text).tolist()
    text_len = len(payload.input_text)
    return PredictResponse(
        validity=max(0.0, min(1.0, 1 - text_len / 1024)),
        entropy=min(1.0, text_len / 1024),
        anchors=["alpha-anchor", "beta-anchor"],
        metadata={"source": "ml-worker", "length": text_len, "vector": vector},
    )


class EmbedRequest(BaseModel):
    text: str = Field(..., min_length=1)


@router.post("/embed", dependencies=[Depends(verify_internal_key)])
def embed(payload: EmbedRequest):
    vector = embed_text(payload.text).tolist()
    return {"vector": vector}


class RetrainRequest(BaseModel):
    dataset_hash_id: Optional[str] = None
    notes: Optional[str] = None


@router.post("/retrain", dependencies=[Depends(verify_internal_key)])
def retrain(payload: RetrainRequest):
    return {
        "job_id": "job-" + (payload.dataset_hash_id or "manual"),
        "status": "queued",
        "notes": payload.notes,
    }


@router.get("/model/versions", dependencies=[Depends(verify_internal_key)])
def model_versions(limit: int = 20):
    versions = list_model_versions(limit)
    return {
        "items": [
            {
                "id": str(v.id),
                "name": v.name,
                "version_tag": v.version_tag,
                "status": v.status,
                "artifact_uri": v.artifact_uri,
                "created_at": v.created_at,
            }
            for v in versions
        ]
    }


@router.get("/model/version/{model_id}", dependencies=[Depends(verify_internal_key)])
def model_version_detail(model_id: str):
    model = get_model_version(model_id)
    if not model:
        raise HTTPException(status_code=404, detail="Model version not found")
    return {
        "id": str(model.id),
        "name": model.name,
        "version_tag": model.version_tag,
        "status": model.status,
        "artifact_uri": model.artifact_uri,
        "metadata": model.meta,
    }

