import React, { useEffect, useState } from 'react';
import { fetchPredictions } from '../../api/predictions';
import { fetchComplianceSummary } from '../../api/compliance';
import KPIBlock from './KPIBlock';
import ValidityOverTimeChart from './ValidityOverTimeChart';
import AnchorCoverageChart from './AnchorCoverageChart';
import { mapPredictionsToLineSeries } from '../../utils/chartHelpers';

const DashboardPage = () => {
  const [predictions, setPredictions] = useState<any[]>([]);
  const [summary, setSummary] = useState<any>(null);

  useEffect(() => {
    const load = async () => {
      try {
        const preds = await fetchPredictions();
        const compliance = await fetchComplianceSummary();
        setPredictions(preds);
        setSummary(compliance);
      } catch (e) {
        console.error('Dashboard load error:', e);
      }
    };

    load();
  }, []);

  if (!summary) return <div>Loading Dashboard...</div>;

  const avgValidity =
    predictions.reduce((acc, p) => acc + p.validity, 0) / Math.max(predictions.length, 1);

  const avgRisk =
    predictions.reduce((acc, p) => acc + p.entropy, 0) / Math.max(predictions.length, 1);

  const policyHits = summary.risky_predictions;
  const driftIndex = summary.low_validity_count;

  const lineData = mapPredictionsToLineSeries(predictions);

  const anchorCounts: Record<string, number> = {};
  predictions.forEach((p) => {
    (p.anchors || []).forEach((anchor: string) => {
      anchorCounts[anchor] = (anchorCounts[anchor] || 0) + 1;
    });
  });
  const barData = Object.entries(anchorCounts).map(([anchor, count]) => ({ anchor, count }));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '32px' }}>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Dashboard</h1>

      <div style={{ display: 'flex', gap: '20px' }}>
        <KPIBlock title="Average Validity" value={avgValidity.toFixed(2)} />
        <KPIBlock title="Average Risk" value={avgRisk.toFixed(2)} />
        <KPIBlock title="Policy Hits (7d)" value={policyHits} />
        <KPIBlock title="Drift Index" value={driftIndex} />
      </div>

      <div>
        <h2 style={{ marginBottom: '12px' }}>Validity Over Time</h2>
        <ValidityOverTimeChart data={lineData} />
      </div>

      <div>
        <h2 style={{ marginBottom: '12px' }}>Anchor Coverage Distribution</h2>
        <AnchorCoverageChart data={barData} />
      </div>
    </div>
  );
};

export default DashboardPage;

import React, { useEffect, useState } from 'react';
import { fetchPredictions } from '../../api/predictions';
import PredictionsFilters from './PredictionsFilters';
import PredictionsTable from './PredictionsTable';

const PredictionsPage = () => {
  const [predictions, setPredictions] = useState<any[]>([]);
  const [filtered, setFiltered] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [minValidity, setMinValidity] = useState(0);
  const [maxRisk, setMaxRisk] = useState(1);
  const [page, setPage] = useState(1);
  const ITEMS_PER_PAGE = 20;

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchPredictions();
        setPredictions(data);
        setFiltered(data);
      } catch (e) {
        console.error('Predictions fetch error:', e);
      }
      setLoading(false);
    };
    load();
  }, []);

  useEffect(() => {
    let items = predictions;
    if (search.trim()) {
      items = items.filter((p) => p.input_text.toLowerCase().includes(search.toLowerCase()));
    }
    items = items.filter((p) => p.validity >= minValidity && p.entropy <= maxRisk);
    setFiltered(items);
    setPage(1);
  }, [search, minValidity, maxRisk, predictions]);

  if (loading) return <div>Loading...</div>;

  const start = (page - 1) * ITEMS_PER_PAGE;
  const end = start + ITEMS_PER_PAGE;
  const pageItems = filtered.slice(start, end);

  return (
    <div>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Predictions</h1>
      <PredictionsFilters
        search={search}
        setSearch={setSearch}
        minValidity={minValidity}
        setMinValidity={setMinValidity}
        maxRisk={maxRisk}
        setMaxRisk={setMaxRisk}
      />
      <PredictionsTable items={pageItems} />
      <div style={{ marginTop: '20px', display: 'flex', gap: '20px' }}>
        <button
          disabled={page <= 1}
          onClick={() => setPage(page - 1)}
          style={{ padding: '8px 14px', borderRadius: '6px', border: '1px solid var(--rg-border)', background: 'var(--rg-bg-card)', color: 'var(--rg-text)' }}
        >
          Prev
        </button>
        <button
          disabled={end >= filtered.length}
          onClick={() => setPage(page + 1)}
          style={{ padding: '8px 14px', borderRadius: '6px', border: '1px solid var(--rg-border)', background: 'var(--rg-bg-card)', color: 'var(--rg-text)' }}
        >
          Next
        </button>
        <div style={{ color: 'var(--rg-text-light)' }}>
          Page {page} / {Math.ceil(filtered.length / ITEMS_PER_PAGE) || 1}
        </div>
      </div>
    </div>
  );
};

