import { useEffect, useRef } from 'react';
import * as echarts from 'echarts';
import getChartTheme from '../../theme/getChartTheme';

const EvidenceGraphViz = ({ graph, onSelect }: { graph: { nodes: any[]; edges: any[] }; onSelect: (node: any) => void }) => {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const theme = getChartTheme();
    const chart = echarts.init(ref.current);

    const nodeColor = (type: string) => {
      switch (type) {
        case 'input':
          return theme.primary;
        case 'token':
          return theme.muted;
        case 'anchor':
          return theme.lineSecondary;
        case 'policy':
          return theme.danger;
        default:
          return theme.muted;
      }
    };

    chart.setOption({
      tooltip: {
        trigger: 'item',
        formatter: (p: any) => p.data.label || p.data.id,
      },
      series: [
        {
          type: 'graph',
          layout: 'force',
          roam: true,
          draggable: true,
          data: graph.nodes.map((n: any) => ({
            id: n.id,
            name: n.label,
            label: { show: false },
            symbolSize: n.type === 'input' ? 50 : 30,
            itemStyle: { color: nodeColor(n.type) },
            rawType: n.type,
            rawNode: n,
          })),
          edges: graph.edges.map((e: any) => ({
            source: e.source,
            target: e.target,
            label: { show: false },
            lineStyle: { width: 1, color: theme.grid },
            rawEdge: e,
          })),
          force: { repulsion: 200, edgeLength: 80 },
        },
      ],
    });

    chart.on('click', (params: any) => {
      if (params.data?.rawNode) {
        onSelect(params.data.rawNode);
      }
    });

    return () => chart.dispose();
  }, [graph, onSelect]);

  return <div ref={ref} style={{ width: '100%', height: '100%' }} />;
};

export default EvidenceGraphViz;

