from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional
from uuid import UUID


@dataclass(frozen=True, slots=True)
class Identity:
    """
    Canonical identity payload propagated through auth layers.

    Every request — whether authenticated via JWT or API key — is represented by
    this tuple to keep RBAC decisions consistent across the platform.
    """

    user_id: Optional[UUID]
    org_id: UUID
    role: str  # admin | manager | analyst | viewer | service
    scopes: List[str] = field(default_factory=list)
    api_key_id: Optional[UUID] = None
    auth_method: str = "jwt"  # jwt | api_key | internal

    def has_scope(self, scope: str) -> bool:
        if "*" in self.scopes:
            return True
        return scope in self.scopes

    def is_admin(self) -> bool:
        return self.role == "admin"

    def allows_cross_org(self) -> bool:
        return self.role == "system" or self.auth_method == "internal"

    def to_claims(self) -> dict:
        return {
            "user_id": str(self.user_id) if self.user_id else None,
            "org_id": str(self.org_id),
            "role": self.role,
            "scopes": self.scopes,
            "api_key_id": str(self.api_key_id) if self.api_key_id else None,
            "auth_method": self.auth_method,
        }

    @staticmethod
    def from_claims(claims: dict) -> "Identity":
        def _parse(value):
            if value is None:
                return None
            return UUID(str(value))

        return Identity(
            user_id=_parse(claims.get("user_id")),
            org_id=UUID(str(claims["org_id"])),
            role=claims["role"],
            scopes=list(claims.get("scopes", [])),
            api_key_id=_parse(claims.get("api_key_id")),
            auth_method=claims.get("auth_method", "jwt"),
        )

from __future__ import annotations

from typing import Callable, Iterable, Optional

import jwt
from fastapi import Depends, Header, HTTPException, Request, Response, status
from sqlalchemy import select

from ..db import get_session, get_tenant_session
from ..models import ApiKey, OrgMembership, User
from .crypto import hash_token
from .identity import Identity
from .jwt import decode_access_token

ACCESS_COOKIE = "rg_access_token"
REFRESH_COOKIE = "rg_refresh_token"
API_KEY_HEADER = "RG-API-Key"


def _extract_bearer_token(authorization: Optional[str]) -> Optional[str]:
    if not authorization:
        return None
    parts = authorization.split()
    if len(parts) != 2:
        return None
    scheme, token = parts
    if scheme.lower() != "bearer":
        return None
    return token


def _get_access_token(request: Request, authorization: Optional[str]) -> str:
    token = _extract_bearer_token(authorization)
    if not token:
        token = request.cookies.get(ACCESS_COOKIE)
    if not token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    return token


def get_jwt_identity(
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    session=Depends(get_session),
) -> Identity:
    token = _get_access_token(request, authorization)
    try:
        decoded = decode_access_token(token)
        identity = Identity.from_claims(decoded)
    except jwt.PyJWTError:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")

    if not identity.user_id:
        raise HTTPException(status_code=401, detail="Invalid identity")

    user = session.get(User, identity.user_id)
    if not user or not user.is_active:
        raise HTTPException(status_code=401, detail="User inactive")

    membership = session.exec(
        select(OrgMembership).where(
            OrgMembership.user_id == identity.user_id,
            OrgMembership.org_id == identity.org_id,
            OrgMembership.status == "active",
        )
    ).first()
    if not membership and not identity.allows_cross_org():
        raise HTTPException(status_code=403, detail="Org access denied")

    payload_version = decoded.get("token_version")
    if payload_version is None or payload_version != user.token_version:
        raise HTTPException(status_code=401, detail="Token expired")

    request.state.identity = identity
    return identity


def _extract_api_key(authorization: Optional[str], header_key: Optional[str]) -> Optional[str]:
    if header_key:
        return header_key.strip()
    if not authorization:
        return None
    parts = authorization.split()
    if len(parts) == 2 and parts[0].lower() == "rg_api_key":
        return parts[1]
    return None


def get_api_key_identity(
    request: Request,
    authorization: Optional[str] = Header(None, alias="Authorization"),
    api_key_header: Optional[str] = Header(None, alias=API_KEY_HEADER),
    session=Depends(get_session),
) -> Identity:
    api_key = _extract_api_key(authorization, api_key_header)
    if not api_key:
        raise HTTPException(status_code=401, detail="API key required")
    try:
        prefix, _ = api_key.split(".", 1)
        prefix = prefix.replace("RG-", "")
    except ValueError:
        raise HTTPException(status_code=401, detail="Malformed API key")

    api_key_record = session.exec(
        select(ApiKey).where(
            ApiKey.prefix == prefix,
            ApiKey.deleted_at.is_(None),
        )
    ).first()
    if not api_key_record:
        raise HTTPException(status_code=401, detail="Unknown API key")

    if hash_token(api_key) != api_key_record.hashed_key:
        raise HTTPException(status_code=401, detail="Invalid API key")

    identity = Identity(
        user_id=None,
        org_id=api_key_record.org_id,
        role="service",
        scopes=api_key_record.scopes or [],
        api_key_id=api_key_record.id,
        auth_method=api_key_record.auth_method or "api_key",
    )
    request.state.identity = identity
    return identity


def tenant_session(identity: Identity = Depends(get_jwt_identity)):
    with get_tenant_session(identity) as session:
        yield session


def require_roles(*roles: str) -> Callable:
    def dependency(identity: Identity = Depends(get_jwt_identity)) -> Identity:
        if identity.role not in roles and not identity.allows_cross_org():
            raise HTTPException(status_code=403, detail="Insufficient role")
        return identity

    return dependency


def require_scopes(*required_scopes: str) -> Callable:
    def dependency(identity: Identity = Depends(get_api_key_identity)) -> Identity:
        if identity.allows_cross_org():
            return identity
        missing = [scope for scope in required_scopes if not identity.has_scope(scope)]
        if missing:
            raise HTTPException(
                status_code=403,
                detail=f"Missing scopes: {', '.join(missing)}",
            )
        return identity

    return dependency


def tenant_session_from_api_key(identity: Identity = Depends(get_api_key_identity)):
    with get_tenant_session(identity) as session:
        yield session


def tenant_session_admin(identity: Identity = Depends(require_roles("admin"))):
    with get_tenant_session(identity) as session:
        yield session, identity

