  const [error, setError] = useState<string>('');

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchBillingOverview();
        setBilling(data);
      } catch (err) {
        console.error('Billing load failed', err);
        setError('Unable to load billing data.');
      }
    };
    load();
  }, []);

  if (error) {
    return <div style={{ padding: '30px' }}>{error}</div>;
  }

  if (!billing) {
    return <div style={{ padding: '30px' }}>Loading billing…</div>;
  }

  const content = (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Billing</h1>
      <BillingOverview data={billing.overview} />
      <UsageBreakdown data={billing.usage} />
      <InvoicesPanel invoices={billing.invoices || []} />
      <PaymentMethodsPanel methods={billing.payment_methods || []} />
      <PricingPanel currentPlan={billing.plan} />
    </div>
  );

  return <BillingProvider>{content}</BillingProvider>;
};

export default BillingPage;

import React, { useEffect, useState } from 'react';
import {
  fetchAPIKeys,
  createAPIKey,
  deleteAPIKey,
  fetchThresholds,
  updateThresholds,
  fetchModelVersions
} from '../../api/settings';
import APIKeysPanel from './APIKeysPanel';
import ThresholdsPanel from './ThresholdsPanel';
import ModelInfoPanel from './ModelInfoPanel';

type ModelRecord = {
  id?: string;
  name: string;
  version?: string;
  updated_at?: string;
};

const normalizeModels = (items: any[]): ModelRecord[] => {
  if (!Array.isArray(items)) return [];
  return items.map((model, idx) => {
    if (typeof model === 'string') {
      return {
        id: `model-${idx}`,
        name: model,
        version: '—',
        updated_at: ''
      };
    }
    return {
      id: model.id ?? `model-${idx}`,
      name: model.name ?? `Model ${idx + 1}`,
      version: model.version ?? model.tag ?? '—',
      updated_at: model.updated_at ?? model.loaded_at ?? ''
    };
  });
};

const SettingsPage = () => {
  const [keys, setKeys] = useState<any[]>([]);
  const [thresholds, setThresholds] = useState<any>(null);
  const [models, setModels] = useState<ModelRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const [keyList, thresholdData, modelList] = await Promise.all([
        fetchAPIKeys(),
        fetchThresholds(),
        fetchModelVersions()
      ]);
      setKeys(Array.isArray(keyList) ? keyList : keyList?.items ?? []);
      setThresholds(thresholdData);
      setModels(normalizeModels(modelList?.items ?? modelList ?? []));
    } catch (err: any) {
      console.error('Settings load error', err);
      setError(err?.error || 'Unable to load settings. Confirm the Flask server (PORT 8081) is running.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) {
    return (
      <div style={{ color: 'var(--rg-text-light)', padding: '40px' }}>Loading Settings…</div>
    );
  }

  if (error || !thresholds) {
    return (
      <div style={{ padding: '40px' }}>
        <div
          style={{
            padding: '24px',
            borderRadius: '8px',
            border: '1px solid var(--rg-border)',
            background: 'var(--rg-bg-card)',
            maxWidth: '520px'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Settings unavailable</h2>
          <p style={{ color: 'var(--rg-text-light)' }}>{error}</p>
          <button
            onClick={load}
            style={{
              padding: '8px 14px',
              borderRadius: '6px',
              border: 'none',
              background: 'var(--rg-primary)',
              color: '#fff',
              cursor: 'pointer'
            }}
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h1 style={{ fontSize: '28px', fontWeight: 600 }}>Settings</h1>

      <APIKeysPanel
        keys={keys}
        onCreate={async (name) => {
          await createAPIKey(name);
          await load();
        }}
        onDelete={async (id) => {
          await deleteAPIKey(id);
          await load();
        }}
      />

      <ThresholdsPanel
        thresholds={thresholds}
        onUpdate={async (payload) => {
          await updateThresholds(payload);
          await load();
        }}
      />

      <ModelInfoPanel models={models} />
    </div>
  );
};

export default SettingsPage;

