    if (token) {
        config.headers.Authorization = `Bearer ${token}`;
    }
    if (role) {
        config.headers['RG-Role'] = role;
    }
    if (org) {
        config.headers['RG-Org-ID'] = org;
    }
    return config;
});
client.interceptors.response.use((response) => response, (error) => {
    console.error('API Error:', error?.response || error);
    return Promise.reject(error?.response?.data || { error: 'Network error' });
});
export default client;

import axios from 'axios';
import { getSession } from '../utils/auth';

const client = axios.create({
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:5000',
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000,
});

client.interceptors.request.use((config) => {
  const { token, role, org } = getSession();
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  if (role) {
    (config.headers as any)['RG-Role'] = role;
  }
  if (org) {
    (config.headers as any)['RG-Org-ID'] = org;
  }
  return config;
});

client.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error('API Error:', error?.response || error);
    return Promise.reject(error?.response?.data || { error: 'Network error' });
  },
);

export default client;

