import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { saveSession, UserRole } from '../../utils/auth';
import fastapiClient from '../../api/fastapiClient';

type LoginResponse = {
  access_token: string;
  org_id: string;
  role: UserRole;
};

const LoginPage = () => {
  const navigate = useNavigate();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [org, setOrg] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleLogin = async () => {
    setError('');

    if (!email.trim()) {
      setError('Email is required.');
      return;
    }

    if (!password.trim()) {
      setError('Password is required.');
      return;
    }

    try {
      setSubmitting(true);
      const payload: { email: string; password: string; org_id?: string } = {
        email: email.trim(),
        password,
      };
      if (org.trim()) {
        payload.org_id = org.trim();
      }

      const { data } = await fastapiClient.post<LoginResponse>('/auth/login', payload);
      saveSession(data.access_token, email.trim(), data.role, data.org_id);
      navigate('/dashboard');
    } catch (err: any) {
      const message =
        err?.detail ||
        err?.error ||
        err?.message ||
        'Unable to sign in. Please check your credentials and try again.';
      setError(typeof message === 'string' ? message : 'Unable to sign in.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      style={{
        display: 'flex',
        height: '100vh',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'var(--rg-bg)'
      }}
    >
      <div
        style={{
          width: '380px',
          padding: '30px',
          background: 'var(--rg-bg-card)',
          borderRadius: '10px',
          border: '1px solid var(--rg-border)'
        }}
      >
        <h2 style={{ marginBottom: '20px' }}>Sign In</h2>

        <div style={{ marginBottom: '20px' }}>
          <label>Email (optional)</label>
          <input
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="user@company.com"
            style={{
              width: '100%',
              padding: '10px',
              borderRadius: '6px',
              border: '1px solid var(--rg-border)',
              background: 'var(--rg-bg)',
              marginTop: '6px'
            }}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label>Password</label>
          <div style={{ position: 'relative' }}>
            <input
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              style={{
                width: '100%',
                padding: '10px',
                borderRadius: '6px',
                border: '1px solid var(--rg-border)',
                background: 'var(--rg-bg)',
                marginTop: '6px'
              }}
            />

            <button
              onClick={() => setShowPassword((prev) => !prev)}
              type="button"
              style={{
                position: 'absolute',
                right: '10px',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'transparent',
                border: 'none',
                color: 'var(--rg-text-light)',
                cursor: 'pointer'
              }}
            >
              {showPassword ? 'Hide' : 'Show'}
            </button>
          </div>
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label>Organization ID (optional)</label>
          <input
            value={org}
            onChange={(e) => setOrg(e.target.value)}
            placeholder="Automatically uses your default organization"
            style={{
              width: '100%',
              padding: '10px',
              borderRadius: '6px',
              border: '1px solid var(--rg-border)',
              background: 'var(--rg-bg)',
              marginTop: '6px'
            }}
          />
        </div>

        {error && (
          <div
            style={{
              marginBottom: '20px',
              padding: '10px',
              background: 'var(--rg-danger-bg)',
              color: 'var(--rg-danger)',
              borderRadius: '6px',
              border: '1px solid var(--rg-danger)'
            }}
          >
            {error}
          </div>
        )}

        <button
          onClick={handleLogin}
          disabled={submitting}
          style={{
            width: '100%',
            padding: '12px',
            borderRadius: '6px',
            background: 'var(--rg-primary)',
            color: '#fff',
            border: 'none',
            cursor: submitting ? 'not-allowed' : 'pointer',
            fontSize: '16px',
            opacity: submitting ? 0.7 : 1
          }}
        >
          {submitting ? 'Signing in...' : 'Sign In'}
        </button>
      </div>
    </div>
  );
};

export default LoginPage;

