    </div>
  </div>
);

export default PredictionsFilters;

import colors from './colors';
import typography from './typography';
import spacing from './spacing';
import shadows from './shadows';

const theme = { colors, typography, spacing, shadows };

export type Theme = typeof theme;

export const setTheme = (next: 'light' | 'dark') => {
  document.documentElement.setAttribute('data-theme', next);
  localStorage.setItem('rg_theme', next);
};

export const initTheme = () => {
  const saved = localStorage.getItem('rg_theme');
  if (saved === 'light' || saved === 'dark') {
    document.documentElement.setAttribute('data-theme', saved);
    return;
  }
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  document.documentElement.setAttribute('data-theme', prefersDark ? 'dark' : 'light');
};

export default theme;

import { useEffect, useState } from 'react';
import { fetchAnchors, deleteAnchor, Anchor } from '../../api/anchors';
import AnchorCreateForm from './AnchorCreateForm';
import AnchorsTable from './AnchorsTable';

const AnchorsPage = () => {
  const [items, setItems] = useState<Anchor[]>([]);

  const load = async () => {
    const data = await fetchAnchors();
    setItems(data);
  };

  useEffect(() => {
    load();
  }, []);

  return (
    <div>
      <h1>Anchors</h1>
      <AnchorCreateForm onCreate={load} />
      <AnchorsTable items={items} onDelete={deleteAnchor} reload={load} />
    </div>
  );
};

export default AnchorsPage;

import { useState } from 'react';

const CreatePolicyModal = ({ onClose, onSubmit }: { onClose: () => void; onSubmit: (payload: any) => void }) => {
  const [name, setName] = useState('');
  const [ruleType, setRuleType] = useState('missing_anchor');
  const [threshold, setThreshold] = useState(0.5);

  const submit = () => {
    onSubmit({ name, rule_type: ruleType, threshold: parseFloat(String(threshold)) });
  };

  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', padding: 20 }}>
      <div style={{ width: 400, background: 'var(--rg-bg-card)', borderRadius: 8, padding: 20, border: '1px solid var(--rg-border)' }}>
        <h3 style={{ marginBottom: 16 }}>New Policy</h3>
        <label>Name</label>
        <input value={name} onChange={(e) => setName(e.target.value)} style={{ width: '100%', padding: 10, border: '1px solid var(--rg-border)', borderRadius: 6, marginBottom: 12 }} />
        <label>Rule Type</label>
        <select value={ruleType} onChange={(e) => setRuleType(e.target.value)} style={{ width: '100%', padding: 10, border: '1px solid var(--rg-border)', borderRadius: 6, marginBottom: 12 }}>
          <option value="missing_anchor">Missing Anchor</option>
          <option value="forbidden_word">Forbidden Word</option>
          <option value="low_validity">Low Validity</option>
          <option value="high_risk">High Risk</option>
        </select>
        <label>Threshold</label>
        <input type="number" step="0.01" min="0" max="1" value={threshold} onChange={(e) => setThreshold(parseFloat(e.target.value) || 0)} style={{ width: '100%', padding: 10, border: '1px solid var(--rg-border)', borderRadius: 6, marginBottom: 20 }} />
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10 }}>
          <button onClick={onClose}>Cancel</button>
          <button onClick={submit} style={{ background: 'var(--rg-primary)', padding: '8px 14px', color: '#fff', borderRadius: 6, border: 'none' }}>
            Create
          </button>
        </div>
      </div>
    </div>
  );
};

export default CreatePolicyModal;

import React, { useState } from 'react';
import CreateAPIKeyModal from './CreateAPIKeyModal';
import DeleteAPIKeyModal from './DeleteAPIKeyModal';

type APIKeysPanelProps = {
  keys: any[];
  onCreate: (name: string) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
};

const APIKeysPanel = ({ keys, onCreate, onDelete }: APIKeysPanelProps) => {
  const [showCreate, setShowCreate] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  return (
    <div
      style={{
        marginTop: '30px',
        background: 'var(--rg-bg-card)',
        border: '1px solid var(--rg-border)',
        borderRadius: '8px',
        padding: '20px'
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2 style={{ fontSize: '20px', fontWeight: 600 }}>API Keys</h2>
        <button
          onClick={() => setShowCreate(true)}
          style={{
            background: 'var(--rg-primary)',
            color: '#fff',
            borderRadius: '6px',
            padding: '8px 12px',
            border: 'none',
            cursor: 'pointer'
          }}
        >
          + Create Key
        </button>
      </div>

      <table width="100%" style={{ marginTop: '16px' }}>
        <thead>
          <tr>
            <th style={{ padding: '12px', textAlign: 'left' }}>Name</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Key</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Created</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {keys.map((key) => (
            <tr key={key.id} style={{ borderBottom: '1px solid var(--rg-border)' }}>
              <td style={{ padding: '12px' }}>{key.name}</td>
              <td style={{ padding: '12px', fontFamily: 'monospace' }}>{key.key ?? key.token}</td>
              <td style={{ padding: '12px' }}>{key.created_at}</td>
              <td style={{ padding: '12px' }}>
                <button
                  onClick={() => setDeleteId(key.id)}
                  style={{
                    padding: '6px 10px',
                    borderRadius: '6px',
                    border: 'none',
                    background: 'var(--rg-danger)',
                    color: '#fff',
                    cursor: 'pointer'
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
          {keys.length === 0 && (
            <tr>
              <td colSpan={4} style={{ padding: '20px', textAlign: 'center', color: 'var(--rg-text-light)' }}>
                No API keys found.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {showCreate && (
        <CreateAPIKeyModal
          onClose={() => setShowCreate(false)}
          onSubmit={async (name) => {
            await onCreate(name);
            setShowCreate(false);
          }}
        />
      )}

      {deleteId && (
        <DeleteAPIKeyModal
          onClose={() => setDeleteId(null)}
          onConfirm={async () => {
            await onDelete(deleteId);
            setDeleteId(null);
          }}
        />
      )}
    </div>
  );
};

export default APIKeysPanel;

import React, { useState } from 'react';
import { createOrgApiKey, revokeOrgApiKey } from '../../api/org';

const OrgApiKeysPanel = ({ keys, onRefresh }: { keys: any[]; onRefresh: () => void }) => {
  const [creating, setCreating] = useState(false);

  const createKey = async () => {
    setCreating(true);
    try {
      await createOrgApiKey('org key');
      onRefresh();
    } catch (error) {
      console.error('Create key failed', error);
    } finally {
      setCreating(false);
    }
  };

  const revokeKey = async (id: string) => {
    await revokeOrgApiKey(id);
    onRefresh();
  };

  return (
    <div
      style={{
        padding: '20px',
        background: 'var(--rg-bg-card)',
        borderRadius: '8px',
        border: '1px solid var(--rg-border)'
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2 style={{ margin: 0 }}>API Keys</h2>
        <button
          onClick={createKey}
          disabled={creating}
          style={{
            padding: '8px 12px',
            borderRadius: '6px',
            background: 'var(--rg-primary)',
            border: 'none',
            color: '#fff',
            cursor: 'pointer',
            opacity: creating ? 0.6 : 1
          }}
        >
          + Create Key
        </button>
      </div>

      <table width="100%" style={{ marginTop: '16px' }}>
        <thead>
          <tr>
            <th style={{ padding: '12px', textAlign: 'left' }}>Name</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Key</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Created</th>
            <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {keys.length === 0 && (
            <tr>
              <td colSpan={4} style={{ padding: '20px', textAlign: 'center', color: 'var(--rg-text-light)' }}>
                No API keys yet.
              </td>
            </tr>
          )}
          {keys.map((key: any) => (
            <tr key={key.id} style={{ borderBottom: '1px solid var(--rg-border)' }}>
              <td style={{ padding: '12px' }}>{key.name}</td>
              <td style={{ padding: '12px', fontFamily: 'monospace' }}>{key.token}</td>
              <td style={{ padding: '12px' }}>{key.created_at}</td>
              <td style={{ padding: '12px' }}>
                <button
                  onClick={() => revokeKey(key.id)}
                  style={{
                    padding: '6px 10px',
                    borderRadius: '6px',
                    border: 'none',
                    background: 'var(--rg-danger)',
                    color: '#fff',
                    cursor: 'pointer'
                  }}
                >
                  Revoke
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default OrgApiKeysPanel;
